import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"OmniRouter: Domando el Caos de los Modelos","description":"Por qué construí OmniRouter — convertir el caos de modelos en un archivo de configuración, con balanceo de carga, failover y streaming real en un binario Go.","frontmatter":{"title":"OmniRouter: Domando el Caos de los Modelos","description":"Por qué construí OmniRouter — convertir el caos de modelos en un archivo de configuración, con balanceo de carga, failover y streaming real en un binario Go."},"headers":[],"relativePath":"es/vibe-stories/story-1/index.md","filePath":"es/vibe-stories/story-1/index.md"}`),a={name:`es/vibe-stories/story-1/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="omnirouter-domando-el-caos-de-los-modelos" tabindex="-1">OmniRouter: Domando el Caos de los Modelos <a class="header-anchor" href="#omnirouter-domando-el-caos-de-los-modelos" aria-label="Permalink to “OmniRouter: Domando el Caos de los Modelos”">​</a></h1><p>El ecosistema de IA avanza a velocidad de scroll. El modelo que impulsaba mi app el lunes está deprecado el viernes, los precios cambian de la noche a la mañana, los tiers gratuitos aparecen y desaparecen. Mis proyectos seguían rompiéndose por razones que no tenían nada que ver con mi código — así que decidí que el caos fuera problema de otro. Ese otro es <strong><a href="https://github.com/Godde3s/omnirouter" target="_blank" rel="noreferrer">OmniRouter</a></strong>.</p><h2 id="un-endpoint-muchos-cerebros" tabindex="-1">Un endpoint, muchos cerebros <a class="header-anchor" href="#un-endpoint-muchos-cerebros" aria-label="Permalink to “Un endpoint, muchos cerebros”">​</a></h2><p>OmniRouter se sitúa entre tu app y cada proveedor de modelos que uses. Tu código habla OpenAI estándar — una base URL, una API key, <code>/v1/chat/completions</code> normal — y el router decide qué cerebro responde realmente: GLM, Qwen, DeepSeek o cualquier endpoint personalizado compatible con OpenAI que registres. Cambiar de modelo pasa a ser un <strong>cambio de configuración, no una refactorización</strong>.</p><h2 id="las-partes-que-exigieron-ingenieria-de-verdad" tabindex="-1">Las partes que exigieron ingeniería de verdad <a class="header-anchor" href="#las-partes-que-exigieron-ingenieria-de-verdad" aria-label="Permalink to “Las partes que exigieron ingeniería de verdad”">​</a></h2><ul><li><strong>Balanceo de carga que entiende de salud</strong> — enrutamiento ponderado con health checks; un proveedor que falla su sonda se enfría y se esquiva en milisegundos.</li><li><strong>Failover sin mentirle al cliente</strong> — si una petición muere en el proveedor A, el router reintenta en el B, y el llamador solo ve un 200 ligeramente más lento.</li><li><strong>Streaming real, de punta a punta</strong> — los tokens SSE cruzan el router sin tocararse, porque un proxy que bufferea streams no es un proxy, es un cuello de botella.</li><li><strong>Un binario estático</strong> — Go puro, stdlib primero, cross-compilado: <code>./omnirouter</code> es toda la historia de despliegue.</li></ul><h2 id="que-demuestra" tabindex="-1">Qué demuestra <a class="header-anchor" href="#que-demuestra" aria-label="Permalink to “Qué demuestra”">​</a></h2><p>OmniRouter es la columna vertebral de mi propio stack de IA — enfrenta a todos los modelos que toca mi tooling de agentes, y viaja dentro de <a href="/Usf/es/projects/hermes-stack/">Hermes Stack</a> como parte de un servidor de IA de un clic. Demuestra que sé diseñar infraestructura de APIs como la producción la necesita: núcleos sin estado, rutas observables y el fallo tratado como caso de primera clase — no como ocurrencia tardía.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};